mapper.select:
select FINPROD_MARKET_ID id, FINPROD_MARKET_ID text, FINPROD_ABBR object from FIN_PRODUCT where 1=1
and FINPROD_TYPE = #{assetType}
AND (FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) OR FINPROD_ABBR like concat('%',concat(#{search},'%')))

select FINPROD_MARKET_ID id, FINPROD_ABBR text, FINPROD_ABBR object from FIN_PRODUCT where 1=1
and FINPROD_TYPE = #{assetType}
AND (FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) OR FINPROD_ABBR like concat('%',concat(#{search},'%')))

select FINPROD_ID id, FINPROD_ID text, FINPROD_ABBR object from FIN_PRODUCT where 1=1
and FINPROD_TYPE =#{finprodType}
AND (FINPROD_ID like concat('%',concat(#{search},'%')) OR FINPROD_ABBR like concat('%',concat(#{search},'%')))

select FINPROD_ID id, FINPROD_ABBR text, FINPROD_ABBR object from FIN_PRODUCT where 1=1
and FINPROD_TYPE =#{finprodType}
AND (FINPROD_ID like concat('%',concat(#{search},'%')) OR FINPROD_ABBR like concat('%',concat(#{search},'%')))

select ssai.TRD_ACCT_ID as id,sci.ACCT_NAME as text
from STL_FIN_PRODUCT_ACCT psa
inner join STL_SEC_ACCT_INFO ssai on psa.ACCT_NO=ssai.SEC_ACCT_ID
inner join STL_CAPACCT_INFO sci on ssai.TRD_ACCT_ID=sci.ACCT_NO


		AND psa.FINPROD_ID =#{portfolioId}


		AND psa.FINPROD_TYPE = #{finprodType}


		AND (psa.ACCT_TYPE IN


				null) or psa.ACCT_TYPE in (

			#{item}
		)

select distinct acct.ACCT_NO as acctno FROM STL_FIN_PRODUCT_ACCT acct where acct.ACCT_TYPE = 'A01'
AND acct.FINPROD_ID =#{finprodId}
AND acct.ACCT_NO = #{initValue}

select bsi.SUBJECT_INTERNAL_CODE as id,bsi.SUBJECT_INTERNAL_NAME as text
from BOK_SUBJECT_INTERNAL bsi


		AND bsi.SUBJECT_LEVEL =#{subjectLevel}


		AND bsi.ACC_FLAG = #{accFlag}


		AND bsi.SUBJECT_TYPE = #{subjectType}


		AND	(SUBJECT_INTERNAL_CODE like concat('%',concat(#{search},'%'))
		OR SUBJECT_INTERNAL_NAME like concat('%',concat(#{search},'%')))
